// Track IDs and titles verified against Spotify's public album embeds.
const moods = {
  R: 'Rainy day',
  G: 'Gym',
  T: 'Road trip',
  F: 'Focus',
  O: 'Throwbacks',
}
const album = (name, artist, songs) => songs.map(([id, title, tags, trackArtist = artist]) => ({
  id, title, artist: trackArtist, album: name,
  moods: [...tags].map(tag => moods[tag]),
  url: `https://open.spotify.com/track/${id}`,
}))

